    text-overflow: ellipsis;
}

::deep .channel-item.active .channel-description {
    color: #cce5ff;
}

::deep .unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

